insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('confucius', '공자', 'Confucius', '동양', '고대', 'BC 551 – BC 479', '유교', '仁', '자기가 원하지 않는 것을 남에게 베풀지 말라.', array['인(仁)', '예(禮)', '정명', '군자', '충서']::text[], '사람다움의 핵심을 인(仁)으로 보고, 예(禮)를 통해 그것을 실천하는 군자의 삶을 강조했다.', array['인(仁): 타인을 사랑하는 마음, 효제(孝悌)에서 출발한다.', '극기복례: 사사로운 욕심을 이기고 예를 회복하는 것이 인이다.', '정명(正名): 각자가 자신의 이름(지위)에 맞는 역할을 다해야 사회가 바로 선다.', '덕치: 형벌보다 도덕과 예로 다스려야 한다.']::text[], '[{"label":"도덕 수양","value":5},{"label":"공동체","value":5},{"label":"예법","value":5},{"label":"개인 자유","value":2}]'::jsonb, array['mencius', 'xunzi', 'zhuxi']::text[], array['ethics-personality-test', 'philosopher-deathmatch']::text[], array['가족의 잘못을 고발해야 할까, 감싸야 할까?']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Konfuzius-1770.jpg?width=480', 'illustration', 'https://commons.wikimedia.org/wiki/File:Konfuzius-1770.jpg', '작자 미상 (1770년경 판화)', 'Public domain', 0, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('mencius', '맹자', 'Mencius', '동양', '고대', 'BC 372 – BC 289', '유교', '善', '측은히 여기는 마음이 없으면 사람이 아니다.', array['성선설', '사단', '호연지기', '왕도정치', '역성혁명']::text[], '인간은 본래 선한 마음(사단)을 지니고 태어나며, 이를 확충하면 누구나 성인이 될 수 있다고 보았다.', array['성선설: 인간의 본성은 선하다.', '사단(측은·수오·사양·시비지심)은 인의예지의 실마리이다.', '호연지기: 의로움을 꾸준히 실천하며 기르는 크고 굳센 기운.', '왕도정치: 백성을 근본으로 하는 정치, 폭군은 바꿀 수 있다(역성혁명).']::text[], '[{"label":"인간 신뢰","value":5},{"label":"도덕 감정","value":5},{"label":"공동체","value":4},{"label":"제도 강조","value":2}]'::jsonb, array['confucius', 'xunzi', 'yihwang']::text[], array['ethics-personality-test', 'philosopher-deathmatch']::text[], array['물에 빠진 아이를 보면 누구나 구하려 할까?']::text[], null, null, null, null, null, 1, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('xunzi', '순자', 'Xunzi', '동양', '고대', 'BC 298? – BC 238?', '유교', '禮', '사람의 본성은 악하니, 선한 것은 인위(人爲)이다.', array['성악설', '화성기위', '예치', '교육']::text[], '인간의 본성은 이기적이므로 예(禮)와 교육을 통해 본성을 교화해야 한다고 주장했다.', array['성악설: 인간은 이익을 좋아하고 욕망을 따르는 본성을 지닌다.', '화성기위: 본성을 변화시켜 인위(작위)를 일으킨다.', '예치: 예는 욕망을 조절하고 사회 질서를 세우는 기준이다.']::text[], '[{"label":"제도 강조","value":5},{"label":"교육","value":5},{"label":"인간 신뢰","value":2},{"label":"현실주의","value":4}]'::jsonb, array['mencius', 'confucius']::text[], array['philosopher-deathmatch']::text[], array['규칙이 없다면 사람들은 선하게 행동할까?']::text[], null, null, null, null, null, 2, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('zhuxi', '주희', 'Zhu Xi', '동양', '중세', '1130 – 1200', '성리학', '理', '사물에 나아가 그 이치를 끝까지 궁구한다.', array['성즉리', '이기론', '격물치지', '거경궁리']::text[], '성리학을 집대성하여 우주와 인간을 이(理)와 기(氣)로 설명하고, 탐구와 수양을 함께 강조했다.', array['성즉리: 인간의 본성이 곧 하늘의 이치이다.', '이기론: 만물은 원리인 이(理)와 재료인 기(氣)로 이루어진다.', '격물치지: 사물의 이치를 탐구하여 앎을 지극히 한다.', '거경궁리: 경(敬)의 태도로 마음을 수양하고 이치를 탐구한다.']::text[], '[{"label":"이성 탐구","value":5},{"label":"도덕 수양","value":5},{"label":"체계성","value":5},{"label":"실천 즉시성","value":2}]'::jsonb, array['wangyangming', 'yihwang', 'yii']::text[], array['philosopher-deathmatch']::text[], '{}', null, null, null, null, null, 3, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('wangyangming', '왕수인', 'Wang Yangming', '동양', '근대', '1472 – 1529', '양명학', '心', '앎은 행함의 시작이요, 행함은 앎의 완성이다.', array['심즉리', '치양지', '지행합일']::text[], '마음이 곧 이치라고 보고, 타고난 양지를 실현하며 앎과 행함을 하나로 일치시킬 것을 강조했다.', array['심즉리: 이치는 바깥 사물이 아니라 내 마음에 있다.', '치양지: 누구에게나 있는 선천적 도덕 판단 능력(양지)을 실현한다.', '지행합일: 참된 앎은 반드시 실천을 동반한다.']::text[], '[{"label":"실천","value":5},{"label":"주체성","value":5},{"label":"이성 탐구","value":3},{"label":"외부 규범","value":2}]'::jsonb, array['zhuxi', 'jeongyakyong']::text[], array['philosopher-deathmatch']::text[], array['알면서도 행하지 않는 것은 아는 것일까?']::text[], null, null, null, null, null, 4, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('yihwang', '이황', 'Yi Hwang (Toegye)', '동양', '근대', '1501 – 1570', '성리학', '敬', '경(敬)은 마음의 주재이자 모든 일의 근본이다.', array['이기호발설', '경 사상', '사단칠정', '이존설']::text[], '이(理)의 능동성을 강조하고, 경(敬)을 통한 엄격한 마음 수양으로 도덕적 인간이 될 것을 강조했다.', array['이기호발설: 사단은 이가 발한 것, 칠정은 기가 발한 것이다.', '이의 능동성과 존귀함을 강조하였다.', '경(敬): 늘 깨어 있으며 마음을 한곳에 집중하는 수양 방법.']::text[], '[{"label":"도덕 수양","value":5},{"label":"이상주의","value":5},{"label":"현실 개혁","value":2},{"label":"이성 탐구","value":4}]'::jsonb, array['yii', 'zhuxi', 'mencius']::text[], array['philosopher-deathmatch']::text[], '{}', null, null, null, null, null, 5, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('yii', '이이', 'Yi I (Yulgok)', '동양', '근대', '1536 – 1584', '성리학', '誠', '이는 통하고 기는 국한된다.', array['기발이승일도설', '이통기국', '성(誠)', '경장']::text[], '이와 기의 불가분성을 강조하고, 현실 문제를 개혁하는 경장(更張)과 성(誠)의 실천을 중시했다.', array['기발이승일도설: 발하는 것은 기이며, 이는 그 위에 탈 뿐이다.', '이통기국: 이는 보편적이고 기는 개별적이다.', '성(誠): 참되고 거짓 없는 마음으로 실천한다.', '경장론: 시대에 맞게 제도를 개혁해야 한다.']::text[], '[{"label":"현실 개혁","value":5},{"label":"도덕 수양","value":4},{"label":"실천","value":5},{"label":"이상주의","value":3}]'::jsonb, array['yihwang', 'jeongyakyong']::text[], array['philosopher-deathmatch']::text[], '{}', null, null, null, null, null, 6, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('jeongyakyong', '정약용', 'Jeong Yak-yong (Dasan)', '동양', '근대', '1762 – 1836', '실학', '實', '덕은 행함으로써 이루어지는 것이다.', array['성기호설', '자주지권', '실천적 덕', '목민']::text[], '인간의 본성을 선을 좋아하는 기호로 보고, 자유 의지(자주지권)로 덕을 실천해야 한다고 했다.', array['성기호설: 본성은 선을 좋아하고 악을 싫어하는 기호(嗜好)이다.', '자주지권: 인간은 선과 악을 스스로 선택할 수 있는 자유를 지닌다.', '덕은 마음속 이치가 아니라 실천을 통해 형성된다.', '목민심서: 백성을 위한 관리의 윤리.']::text[], '[{"label":"실천","value":5},{"label":"자유 의지","value":5},{"label":"현실 개혁","value":5},{"label":"형이상학","value":2}]'::jsonb, array['yii', 'wangyangming', 'mencius']::text[], array['ethics-personality-test', 'philosopher-deathmatch']::text[], array['공직자는 어디까지 백성을 위해 규칙을 어길 수 있을까?']::text[], null, null, null, null, null, 7, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('wonhyo', '원효', 'Wonhyo', '동양', '중세', '617 – 686', '불교', '和', '모든 것은 오직 마음이 만든 것이다.', array['일심', '화쟁', '무애', '정토 신앙']::text[], '모든 것을 일심(一心)으로 보고, 서로 다른 주장을 조화시키는 화쟁 사상으로 불교 대중화에 힘썼다.', array['일심: 모든 존재와 현상의 근원은 하나의 마음이다.', '화쟁: 다양한 종파의 대립을 더 높은 차원에서 조화시킨다.', '무애: 걸림 없는 삶으로 민중 속에서 불교를 전했다.']::text[], '[{"label":"조화","value":5},{"label":"포용성","value":5},{"label":"대중성","value":5},{"label":"체계 정립","value":3}]'::jsonb, array['uicheon', 'jinul']::text[], array['philosopher-deathmatch']::text[], array['서로 다른 주장은 반드시 하나만 옳을까?']::text[], null, null, null, null, null, 8, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('uicheon', '의천', 'Uicheon', '동양', '중세', '1055 – 1101', '불교(천태종)', '雙', '교와 관을 함께 닦아야 한다.', array['교관겸수', '천태종', '교선 통합']::text[], '교종을 중심으로 선종을 통합하려 했으며, 교리 공부와 참선을 함께 닦는 교관겸수를 강조했다.', array['교관겸수: 경전 공부(교)와 마음 관찰(관)을 함께 수행한다.', '천태종 개창으로 교종 중심의 교선 통합을 시도했다.']::text[], '[{"label":"균형","value":5},{"label":"교리 탐구","value":5},{"label":"조화","value":4},{"label":"대중성","value":3}]'::jsonb, array['jinul', 'wonhyo']::text[], array['philosopher-deathmatch']::text[], '{}', null, null, null, null, null, 9, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('jinul', '지눌', 'Jinul', '동양', '중세', '1158 – 1210', '불교(조계종)', '悟', '땅에서 넘어진 자는 땅을 짚고 일어나야 한다.', array['정혜쌍수', '돈오점수', '선교 일치']::text[], '선종을 중심으로 교종을 포용하며, 단번에 깨닫고 점진적으로 닦는 돈오점수를 주장했다.', array['돈오점수: 자기 마음이 곧 부처임을 단번에 깨닫고, 습기를 점차 닦는다.', '정혜쌍수: 선정(定)과 지혜(慧)를 함께 닦는다.', '선종 중심의 교선 통합을 추구했다.']::text[], '[{"label":"균형","value":5},{"label":"수행","value":5},{"label":"깨달음","value":5},{"label":"교리 탐구","value":3}]'::jsonb, array['uicheon', 'wonhyo']::text[], array['philosopher-deathmatch']::text[], '{}', null, null, null, null, null, 10, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('laozi', '노자', 'Laozi', '동양', '고대', 'BC 6세기경', '도가', '道', '가장 좋은 것은 물과 같다.', array['도', '무위자연', '상선약수', '소국과민']::text[], '인위적인 것을 버리고 자연의 흐름을 따르는 무위자연의 삶과 이상 사회(소국과민)를 제시했다.', array['도(道): 만물의 근원이자 자연의 원리.', '무위자연: 억지로 꾸미지 않고 자연에 따른다.', '상선약수: 겸손하고 다투지 않는 물처럼 살아라.', '소국과민: 작은 나라, 적은 백성의 소박한 공동체.']::text[], '[{"label":"자연","value":5},{"label":"자유","value":4},{"label":"겸손","value":5},{"label":"제도 강조","value":1}]'::jsonb, array['zhuangzi', 'confucius']::text[], array['ethics-personality-test', 'philosopher-deathmatch']::text[], array['더 많이 발전하는 것이 항상 더 좋은 걸까?']::text[], null, null, null, null, null, 11, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('zhuangzi', '장자', 'Zhuangzi', '동양', '고대', 'BC 369? – BC 286?', '도가', '蝶', '내가 나비 꿈을 꾼 것인가, 나비가 내 꿈을 꾸는 것인가.', array['제물', '소요유', '심재', '좌망']::text[], '만물은 본래 평등하다는 제물론과, 모든 구속에서 벗어난 절대 자유(소요유)의 경지를 추구했다.', array['제물론: 만물은 도의 관점에서 모두 평등하다.', '소요유: 어떤 것에도 얽매이지 않고 노니는 절대 자유.', '심재·좌망: 마음을 비우고 자신을 잊는 수양.']::text[], '[{"label":"자유","value":5},{"label":"상대주의","value":5},{"label":"자연","value":5},{"label":"사회 참여","value":1}]'::jsonb, array['laozi']::text[], array['philosopher-mystery', 'philosopher-deathmatch']::text[], array['지금 이 순간이 꿈이 아니라고 증명할 수 있을까?']::text[], null, null, null, null, null, 12, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('sophists', '소피스트', 'Sophists', '서양', '고대', 'BC 5세기', '소피스트 (프로타고라스 등)', 'Σ', '인간은 만물의 척도이다. — 프로타고라스', array['상대주의', '회의주의', '수사학', '노모스']::text[], '보편적 진리를 부정하고 진리와 가치는 개인과 사회에 따라 상대적이라고 주장했다.', array['윤리적 상대주의: 옳고 그름의 기준은 사람·사회마다 다르다.', '자연(피시스)과 관습(노모스)을 구분했다.', '설득의 기술(수사학)을 가르쳤다.']::text[], '[{"label":"상대주의","value":5},{"label":"설득력","value":5},{"label":"보편 진리","value":1},{"label":"실용성","value":4}]'::jsonb, array['socrates', 'plato']::text[], array['philosopher-deathmatch']::text[], array['모든 문화의 도덕은 똑같이 옳을까?']::text[], null, null, null, null, null, 13, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('socrates', '소크라테스', 'Socrates', '서양', '고대', 'BC 470 – BC 399', '고대 그리스', 'Ω', '음미하지 않는 삶은 살 가치가 없다.', array['무지의 자각', '문답법', '지덕복 합일', '영혼을 돌봄']::text[], '자신의 무지를 자각하고 대화를 통해 보편적 진리를 찾아야 하며, 덕을 아는 자가 덕을 행한다고 보았다.', array['너 자신을 알라: 무지를 자각하는 것이 앎의 출발이다.', '문답법(산파술): 질문을 통해 상대가 스스로 진리를 찾게 한다.', '지덕복 합일: 앎과 덕과 행복은 하나이다.', '주지주의: 악행은 무지에서 비롯된다.']::text[], '[{"label":"이성","value":5},{"label":"대화","value":5},{"label":"보편 진리","value":5},{"label":"감정","value":2}]'::jsonb, array['plato', 'sophists', 'aristotle']::text[], array['ethics-personality-test', 'philosopher-survival', 'philosopher-deathmatch']::text[], array['부당한 법이라도 지켜야 할까?']::text[], null, 'bust', null, null, null, 14, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('plato', '플라톤', 'Plato', '서양', '고대', 'BC 427 – BC 347', '고대 그리스', 'Π', '철학자가 왕이 되거나 왕이 철학을 하기 전까지 나라의 불행은 그치지 않는다.', array['이데아', '영혼 삼분설', '4주덕', '철인 통치']::text[], '참된 실재인 이데아를 추구하며, 영혼과 국가의 각 부분이 조화를 이룰 때 정의가 실현된다고 보았다.', array['이데아론: 감각 세계 너머 변하지 않는 참된 실재가 있다.', '영혼 삼분설: 이성·기개·욕망 — 각각 지혜·용기·절제의 덕.', '정의: 각 부분이 제 역할을 다하며 조화를 이룬 상태.', '철인 통치: 선의 이데아를 아는 철학자가 다스려야 한다.']::text[], '[{"label":"이성","value":5},{"label":"이상주의","value":5},{"label":"공동체","value":4},{"label":"감각 경험","value":1}]'::jsonb, array['socrates', 'aristotle', 'augustine']::text[], array['ethics-personality-test', 'philosopher-survival', 'philosopher-deathmatch']::text[], array['가장 지혜로운 사람이 모든 결정을 내려야 할까?']::text[], null, 'bust', null, null, null, 15, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('aristotle', '아리스토텔레스', 'Aristotle', '서양', '고대', 'BC 384 – BC 322', '고대 그리스', 'A', '한 마리 제비가 봄을 만드는 것은 아니다.', array['행복(에우다이모니아)', '중용', '습관화', '실천적 지혜']::text[], '인간의 궁극적 목적은 행복이며, 중용의 덕을 습관화하여 탁월하게 기능을 발휘할 때 행복해진다고 보았다.', array['행복: 이성에 따른 영혼의 탁월한 활동.', '지적 덕은 교육으로, 품성적 덕은 습관으로 길러진다.', '중용: 지나침과 모자람 사이의 적절함.', '인간은 폴리스적(사회적) 동물이다.']::text[], '[{"label":"덕","value":5},{"label":"균형","value":5},{"label":"공동체","value":4},{"label":"규칙 절대성","value":2}]'::jsonb, array['plato', 'aquinas', 'socrates']::text[], array['ethics-personality-test', 'philosopher-survival', 'philosopher-deathmatch']::text[], array['용기와 무모함의 경계는 어디일까?']::text[], null, 'bust', null, null, null, 16, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('epicurus', '에피쿠로스', 'Epicurus', '서양', '고대', 'BC 341 – BC 270', '에피쿠로스학파', 'ε', '죽음은 우리에게 아무것도 아니다.', array['쾌락주의', '아타락시아', '정신적 쾌락', '은둔']::text[], '고통 없는 마음의 평정(아타락시아)을 최고의 쾌락으로 보고, 소박하고 절제된 삶을 권했다.', array['쾌락은 선이고 고통은 악이다. 단, 정신적·지속적 쾌락이 중요하다.', '아타락시아: 마음의 동요가 없는 평온한 상태.', '죽음에 대한 두려움에서 벗어나라.']::text[], '[{"label":"쾌락","value":4},{"label":"평정","value":5},{"label":"절제","value":4},{"label":"사회 참여","value":1}]'::jsonb, array['stoics', 'bentham']::text[], array['philosopher-survival', 'philosopher-deathmatch']::text[], array['행복한 돼지와 불행한 소크라테스, 누가 더 행복할까?']::text[], null, null, null, null, null, 17, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('stoics', '스토아', 'Stoics', '서양', '고대', 'BC 3세기 – AD 2세기', '스토아학파 (제논, 세네카, 아우렐리우스)', 'Λ', '우리를 괴롭히는 것은 사건이 아니라 그 사건에 대한 생각이다. — 에픽테토스', array['아파테이아', '자연법', '세계 시민주의', '이성']::text[], '우주의 이성(로고스)에 따라 살며 정념에서 벗어난 부동심(아파테이아)을 추구했다.', array['자연에 따라 살아라: 우주를 지배하는 이성의 법칙을 따른다.', '아파테이아: 정념에 흔들리지 않는 마음.', '모든 인간은 이성을 지닌 세계 시민이다.']::text[], '[{"label":"이성","value":5},{"label":"평정","value":5},{"label":"보편성","value":5},{"label":"감정","value":1}]'::jsonb, array['epicurus', 'kant']::text[], array['philosopher-survival', 'philosopher-deathmatch']::text[], array['바꿀 수 없는 일에 분노하는 것은 의미가 있을까?']::text[], null, null, null, null, null, 18, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('augustine', '아우구스티누스', 'Augustine', '서양', '중세', '354 – 430', '교부 철학', '✝', '당신 안에서 쉬기까지 우리 마음은 평안하지 않습니다.', array['신앙', '은총', '자유 의지', '신국']::text[], '플라톤 철학을 바탕으로 신앙을 체계화하였으며, 악은 선의 결핍이고 행복은 신의 은총으로 가능하다고 했다.', array['악은 실체가 아니라 선의 결핍이다.', '인간은 자유 의지를 잘못 사용하여 죄를 짓는다.', '신의 은총을 통해 구원과 참된 행복에 이른다.', '믿음·소망·사랑의 신학적 덕.']::text[], '[{"label":"신앙","value":5},{"label":"내면 성찰","value":5},{"label":"이성","value":3},{"label":"현세 중시","value":1}]'::jsonb, array['plato', 'aquinas']::text[], array['philosopher-deathmatch']::text[], '{}', null, null, null, null, null, 19, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('aquinas', '아퀴나스', 'Thomas Aquinas', '서양', '중세', '1225 – 1274', '스콜라 철학', '⚖', '은총은 자연을 파괴하지 않고 완성한다.', array['자연법', '신앙과 이성의 조화', '영원법']::text[], '아리스토텔레스 철학으로 신앙을 체계화하고, 인간 이성으로 알 수 있는 자연법 윤리를 제시했다.', array['신앙과 이성은 조화를 이룬다.', '자연법: 영원법이 인간 이성에 새겨진 것. "선은 행하고 악은 피하라."', '인정법은 자연법에 근거해야 한다.']::text[], '[{"label":"체계성","value":5},{"label":"신앙","value":5},{"label":"이성","value":4},{"label":"보편 규범","value":5}]'::jsonb, array['aristotle', 'augustine']::text[], array['philosopher-deathmatch']::text[], array['자연법에 어긋나는 법도 법일까?']::text[], null, null, null, null, null, 20, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('descartes', '데카르트', 'René Descartes', '서양', '근대', '1596 – 1650', '합리론', '∴', '나는 생각한다, 그러므로 나는 존재한다.', array['방법적 회의', '코기토', '연역법', '심신 이원론']::text[], '모든 것을 의심하는 방법적 회의를 통해 확실한 진리에 도달하고, 이성을 지식의 근원으로 보았다.', array['방법적 회의: 조금이라도 의심스러운 것은 모두 의심한다.', '코기토: 의심하는 나의 존재는 의심할 수 없다.', '연역법: 확실한 원리에서 출발해 지식을 이끈다.', '정념은 이성으로 통제해야 한다.']::text[], '[{"label":"이성","value":5},{"label":"회의","value":5},{"label":"감각 경험","value":1},{"label":"체계성","value":4}]'::jsonb, array['spinoza', 'bacon']::text[], array['philosopher-mystery', 'philosopher-deathmatch']::text[], array['내가 보는 세상이 가상현실이라면?']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Frans_Hals_-_Portret_van_René_Descartes.jpg?width=480', 'painting', 'https://commons.wikimedia.org/wiki/File:Frans_Hals_-_Portret_van_René_Descartes.jpg', 'Frans Hals 이후 (17세기 유화)', 'Public domain', 21, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('spinoza', '스피노자', 'Baruch Spinoza', '서양', '근대', '1632 – 1677', '합리론', '∞', '내일 세상이 멸망하더라도 나는 오늘 한 그루의 사과나무를 심겠다. (전해지는 말)', array['범신론', '영원의 상', '코나투스', '자유']::text[], '신과 자연을 동일시하고, 만물을 영원의 관점에서 이성적으로 인식할 때 정념에서 벗어나 자유로워진다고 했다.', array['신 즉 자연: 신은 자연 그 자체이다.', '코나투스: 모든 존재는 자기 존재를 보존하려 한다.', '영원의 상 아래에서 사물을 볼 때 참된 자유와 행복에 이른다.']::text[], '[{"label":"이성","value":5},{"label":"체계성","value":5},{"label":"자유","value":4},{"label":"감정","value":2}]'::jsonb, array['descartes', 'stoics']::text[], array['philosopher-deathmatch']::text[], '{}', null, null, null, null, null, 22, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('bacon', '베이컨', 'Francis Bacon', '서양', '근대', '1561 – 1626', '경험론', '⚗', '아는 것이 힘이다.', array['귀납법', '4대 우상', '경험', '자연 지배']::text[], '관찰과 실험에 기초한 귀납법을 강조하고, 올바른 인식을 방해하는 4가지 우상을 버려야 한다고 했다.', array['귀납법: 개별 관찰에서 일반 법칙을 이끌어 낸다.', '4대 우상: 종족·동굴·시장·극장의 우상.', '지식은 자연을 지배하고 인간의 삶을 개선하는 힘이다.']::text[], '[{"label":"감각 경험","value":5},{"label":"실용성","value":5},{"label":"과학","value":5},{"label":"형이상학","value":1}]'::jsonb, array['hume', 'descartes']::text[], array['philosopher-deathmatch']::text[], array['과학 기술로 자연을 마음껏 이용해도 될까?']::text[], null, null, null, null, null, 23, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('hume', '흄', 'David Hume', '서양', '근대', '1711 – 1776', '경험론', '♡', '이성은 정념의 노예이며, 노예여야만 한다.', array['도덕 감정', '공감', '이성은 정념의 노예', '회의주의']::text[], '도덕은 이성이 아니라 감정에서 비롯되며, 공감(동정심)이 도덕 판단의 기초라고 보았다.', array['이성은 사실을 판단할 뿐, 행위의 동기는 감정이다.', '시인과 부인의 감정이 도덕적 선악을 결정한다.', '공감: 타인의 감정을 함께 느끼는 능력이 도덕의 기초.', '인과 관계는 습관적 연상일 뿐이다.']::text[], '[{"label":"감정","value":5},{"label":"공감","value":5},{"label":"감각 경험","value":5},{"label":"이성","value":2}]'::jsonb, array['bacon', 'kant', 'bentham']::text[], array['ethics-personality-test', 'philosopher-deathmatch']::text[], array['옳다고 "느끼는" 것이 옳은 것일까?']::text[], null, null, null, null, null, 24, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('kant', '칸트', 'Immanuel Kant', '서양', '근대', '1724 – 1804', '의무론', '★', '너의 의지의 준칙이 항상 보편적 입법의 원리가 될 수 있도록 행위하라.', array['선의지', '정언명령', '자율', '의무']::text[], '결과가 아니라 의무에서 비롯된 선의지가 도덕의 핵심이며, 이성이 스스로 세운 보편 법칙을 따르는 것이 자율이라고 했다.', array['선의지: 그 자체로 무조건 선한 유일한 것.', '정언명령: "~라면"이라는 조건 없이 무조건 따라야 하는 도덕 법칙.', '보편화 가능성: 모두가 따라도 모순이 없는 준칙만 도덕적이다.', '인격 존중: 인간을 언제나 목적으로 대하고 결코 수단으로만 대하지 마라.']::text[], '[{"label":"의무","value":5},{"label":"결과","value":1},{"label":"이성","value":5},{"label":"감정","value":1}]'::jsonb, array['bentham', 'mill', 'hume', 'stoics']::text[], array['ethics-personality-test', 'philosopher-survival', 'ethics-dilemma', 'philosopher-deathmatch']::text[], array['친구를 숨겨 준 상황에서, 살인자에게 거짓말을 해도 될까?', '다섯 명을 구하기 위해 한 명을 희생해도 될까?']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Immanuel_Kant_(painted_portrait).jpg?width=480', 'painting', 'https://commons.wikimedia.org/wiki/File:Immanuel_Kant_(painted_portrait).jpg', '작자 미상 (18세기 후반 유화)', 'Public domain', 25, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('bentham', '벤담', 'Jeremy Bentham', '서양', '근대', '1748 – 1832', '양적 공리주의', '∑', '최대 다수의 최대 행복.', array['유용성의 원리', '쾌락 계산', '양적 공리주의', '제재']::text[], '쾌락은 양적으로 계산할 수 있으며, 최대 다수의 최대 행복을 가져오는 행위가 옳다고 보았다.', array['유용성의 원리: 행복을 증진하는 행위가 옳다.', '쾌락 계산법: 강도·지속성·확실성 등 7가지 기준.', '쾌락에는 질적 차이가 없고 양적 차이만 있다.', '4가지 제재(물리·정치·도덕·종교)가 행위를 이끈다.']::text[], '[{"label":"의무","value":1},{"label":"결과","value":5},{"label":"이성","value":4},{"label":"감정","value":3}]'::jsonb, array['mill', 'kant', 'epicurus']::text[], array['ethics-personality-test', 'philosopher-survival', 'ethics-dilemma', 'philosopher-deathmatch']::text[], array['다섯 명을 구하기 위해 한 명을 희생해도 될까?']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Jeremy_Bentham_by_Henry_William_Pickersgill_detail.jpg?width=480', 'painting', 'https://commons.wikimedia.org/wiki/File:Jeremy_Bentham_by_Henry_William_Pickersgill_detail.jpg', 'Henry William Pickersgill (19세기 유화)', 'Public domain', 26, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('mill', '밀', 'John Stuart Mill', '서양', '근대', '1806 – 1873', '질적 공리주의', '◎', '만족한 돼지보다 불만족한 인간이, 만족한 바보보다 불만족한 소크라테스가 낫다.', array['질적 공리주의', '내적 제재', '자유론', '위해 원리']::text[], '쾌락에는 질적 차이가 있으며 정신적 쾌락이 더 높다고 보고, 타인에게 해가 되지 않는 한 개인의 자유를 존중했다.', array['쾌락에는 질적 차이가 있다 — 정신적 쾌락이 더 고급이다.', '내적 제재: 양심이 도덕적 행위를 이끈다.', '위해 원리: 타인에게 해를 끼치지 않는 한 개인의 자유는 보장되어야 한다.']::text[], '[{"label":"의무","value":2},{"label":"결과","value":5},{"label":"자유","value":5},{"label":"감정","value":3}]'::jsonb, array['bentham', 'kant']::text[], array['ethics-personality-test', 'philosopher-survival', 'ethics-dilemma', 'philosopher-deathmatch']::text[], array['행복한 돼지와 불행한 소크라테스, 누가 더 행복할까?']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/John_Stuart_Mill_by_London_Stereoscopic_Company,_c1870.jpg?width=480', 'photo', 'https://commons.wikimedia.org/wiki/File:John_Stuart_Mill_by_London_Stereoscopic_Company,_c1870.jpg', 'London Stereoscopic Company (1870년경 사진)', 'Public domain', 27, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('kierkegaard', '키르케고르', 'Søren Kierkegaard', '서양', '현대', '1813 – 1855', '유신론적 실존주의', '?', '나에게 진리인 진리, 내가 그것을 위해 살고 죽을 수 있는 이념을 찾는 것이 중요하다.', array['주체적 진리', '실존의 3단계', '절망', '신앙의 도약']::text[], '객관적 진리보다 나에게 의미 있는 주체적 진리를 강조하고, 미적·윤리적·종교적 실존 단계를 제시했다.', array['주체적 진리: 내가 그것을 위해 살 수 있는 진리.', '실존의 3단계: 미적 → 윤리적 → 종교적 실존.', '절망은 "죽음에 이르는 병"이며, 신 앞의 단독자로 설 때 극복된다.']::text[], '[{"label":"주체성","value":5},{"label":"신앙","value":5},{"label":"불안 성찰","value":5},{"label":"사회 체계","value":1}]'::jsonb, array['jaspers', 'sartre', 'heidegger']::text[], array['philosopher-deathmatch']::text[], '{}', null, null, null, null, null, 28, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('jaspers', '야스퍼스', 'Karl Jaspers', '서양', '현대', '1883 – 1969', '유신론적 실존주의', '▲', '한계 상황을 경험하는 것과 실존하는 것은 같은 것이다.', array['한계 상황', '실존적 교제', '초월자', '사랑하는 투쟁']::text[], '죽음·고통·죄책 같은 한계 상황에서 좌절할 때 초월자를 만나 참된 실존에 이를 수 있다고 보았다.', array['한계 상황: 죽음, 고통, 투쟁, 죄책처럼 피할 수 없는 상황.', '한계 상황에서의 좌절이 초월자를 향한 계기가 된다.', '실존적 교제: 서로의 실존을 일깨우는 "사랑하는 투쟁".']::text[], '[{"label":"주체성","value":5},{"label":"소통","value":5},{"label":"초월","value":4},{"label":"사회 체계","value":2}]'::jsonb, array['kierkegaard', 'heidegger']::text[], array['philosopher-deathmatch']::text[], '{}', null, null, null, null, null, 29, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('heidegger', '하이데거', 'Martin Heidegger', '서양', '현대', '1889 – 1976', '실존 철학', '◐', '언어는 존재의 집이다.', array['현존재', '죽음에 이르는 존재', '세인', '본래적 실존']::text[], '자신의 죽음을 자각하고 미리 달려가 볼 때, 평균적 일상(세인)에서 벗어나 본래적 실존을 회복한다고 보았다.', array['현존재(다자인): 자기 존재를 문제 삼는 존재, 인간.', '세인(das Man): 남들처럼 살아가는 비본래적 삶.', '죽음에 이르는 존재: 죽음을 자각할 때 본래적 자기를 찾는다.']::text[], '[{"label":"주체성","value":5},{"label":"죽음 성찰","value":5},{"label":"언어·존재","value":5},{"label":"사회 체계","value":2}]'::jsonb, array['kierkegaard', 'jaspers', 'sartre']::text[], array['philosopher-mystery', 'philosopher-deathmatch']::text[], '{}', null, null, null, null, null, 30, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.philosophers (id, name, name_en, region, era, period, school, symbol, quote, keywords, summary, ideas, stats, related, games, dilemmas, image, image_type, image_source, image_creator, image_license, sort_order, visibility, class_ids) values ('sartre', '사르트르', 'Jean-Paul Sartre', '서양', '현대', '1905 – 1980', '무신론적 실존주의', '∅', '실존은 본질에 앞선다.', array['실존은 본질에 앞선다', '자유', '책임', '앙가주망']::text[], '인간은 정해진 본질 없이 세계에 던져진 존재로, 스스로 선택하며 자신을 만들어 가고 그 선택에 책임져야 한다고 했다.', array['실존은 본질에 앞선다: 인간은 스스로 자신을 만들어 간다.', '인간은 자유롭도록 선고받았다.', '선택에는 인류 전체에 대한 책임이 따른다.', '앙가주망: 사회 참여를 통해 자유를 실현한다.']::text[], '[{"label":"자유","value":5},{"label":"책임","value":5},{"label":"주체성","value":5},{"label":"정해진 규범","value":1}]'::jsonb, array['kierkegaard', 'heidegger', 'jaspers']::text[], array['ethics-personality-test', 'philosopher-survival', 'philosopher-deathmatch']::text[], array['정해진 진로가 없다면, 나는 무엇을 기준으로 선택할까?']::text[], null, null, null, null, null, 31, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.games (id, title, tagline, description, type, status, external_url, internal_route, thumbnail, icon, accent, featured, save_result, duration, players, how_to, philosophers, sort_order, visibility, class_ids) values ('ethics-personality-test', '윤리 사상가 심리테스트', '나는 어떤 철학자와 닮았을까?', '일상 속 선택 상황에 답하면서 나의 윤리적 사고방식이 어떤 사상가와 가장 가까운지 알아보는 테스트입니다. 별도 프로젝트로 제작되어 있으며, 곧 PHILO LAB과 연결됩니다.', '심리테스트', 'external', null, null, null, '🧭', 'gold', true, true, '5분', '개인', array['상황 질문에 솔직하게 답한다', '나와 닮은 사상가 결과를 확인한다', '결과를 친구와 비교하고 이유를 이야기해 본다']::text[], array['kant', 'bentham', 'aristotle', 'confucius', 'sartre']::text[], 0, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.games (id, title, tagline, description, type, status, external_url, internal_route, thumbnail, icon, accent, featured, save_result, duration, players, how_to, philosophers, sort_order, visibility, class_ids) values ('philosopher-survival', '철학자 생존게임', '철학자들과 살아남는 가상의 세계', '위기 상황이 닥친 가상의 세계에서 철학자들과 함께 선택을 내리며 살아남는 게임입니다. 별도 프로젝트로 제작되어 있으며, 곧 PHILO LAB과 연결됩니다.', '생존게임', 'external', null, null, null, '🏝️', 'green', true, false, '15~20분', '개인 / 모둠', array['함께할 철학자를 고른다', '위기 상황마다 선택을 내린다', '선택의 근거가 된 사상을 돌아본다']::text[], array['socrates', 'plato', 'aristotle', 'kant', 'mill', 'sartre']::text[], 1, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.games (id, title, tagline, description, type, status, external_url, internal_route, thumbnail, icon, accent, featured, save_result, duration, players, how_to, philosophers, sort_order, visibility, class_ids) values ('ethics-dilemma', '윤리 딜레마', '당신의 선택은?', '트롤리 문제부터 AI·생명윤리까지, 정답이 없는 딜레마 앞에서 선택하고 다른 친구들의 선택과 비교해 보는 활동입니다.', '딜레마', 'coming', null, null, null, '⚖️', 'navy', true, false, '10분', '개인 / 학급', array['딜레마 상황을 읽는다', '선택하고 이유를 쓴다', '사상가들의 관점과 비교한다']::text[], array['kant', 'bentham', 'mill']::text[], 2, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.games (id, title, tagline, description, type, status, external_url, internal_route, thumbnail, icon, accent, featured, save_result, duration, players, how_to, philosophers, sort_order, visibility, class_ids) values ('philosopher-deathmatch', '철학자 데스매치', '역사 속 철학자들의 치열한 논쟁', '두 철학자가 하나의 쟁점을 두고 맞붙습니다. 각 팀은 철학자의 입장이 되어 논거 카드를 내고, 청중의 판정으로 승부를 가립니다.', '대결', 'coming', null, null, null, '⚔️', 'gold', true, false, '20분', '모둠 대항', array['대결할 철학자와 쟁점을 뽑는다', '논거 카드로 주장과 반박을 펼친다', '청중 투표로 승자를 가린다']::text[], array['kant', 'bentham', 'mencius', 'xunzi']::text[], 3, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.games (id, title, tagline, description, type, status, external_url, internal_route, thumbnail, icon, accent, featured, save_result, duration, players, how_to, philosophers, sort_order, visibility, class_ids) values ('philosopher-mystery', '철학자 추리게임', '단서를 모아 철학자의 생각을 추리하라', '명언, 키워드, 일화 등 흩어진 단서를 모아 어떤 철학자인지, 그리고 그가 무엇을 주장했는지 추리합니다.', '추리', 'coming', null, null, null, '🔍', 'green', true, false, '10분', '개인 / 모둠', array['단서 카드를 하나씩 연다', '용의 철학자를 좁혀 간다', '최소한의 단서로 정답을 맞힌다']::text[], array['descartes', 'zhuangzi', 'heidegger']::text[], 4, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.games (id, title, tagline, description, type, status, external_url, internal_route, thumbnail, icon, accent, featured, save_result, duration, players, how_to, philosophers, sort_order, visibility, class_ids) values ('kant-vs-bentham', '칸트 vs 벤담', '의무인가, 결과인가? 데스매치 1라운드', '거짓말, 트롤리 문제, 약속 지키기 — 의무론과 공리주의가 같은 상황에서 어떻게 다른 답을 내리는지 겨룹니다.', '대결', 'coming', null, null, null, '🥊', 'navy', false, false, '15분', '모둠 대항', array['상황 카드를 뽑는다', '칸트 팀과 벤담 팀이 각자 판단과 근거를 낸다', '청중이 더 설득력 있는 쪽에 투표한다']::text[], array['kant', 'bentham']::text[], 5, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.games (id, title, tagline, description, type, status, external_url, internal_route, thumbnail, icon, accent, featured, save_result, duration, players, how_to, philosophers, sort_order, visibility, class_ids) values ('philo-quiz', '철학 OX 스피드 퀴즈', '30초 안에 맞혀라!', '단원별 핵심 개념을 OX 퀴즈로 빠르게 점검합니다. 시험 대비용으로도 활용할 수 있습니다.', '퀴즈', 'coming', null, null, null, '⏱️', 'navy', false, false, '3분', '개인', array['단원을 고른다', '제한 시간 안에 OX를 고른다', '틀린 문제 해설을 확인한다']::text[], '{}', 6, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.games (id, title, tagline, description, type, status, external_url, internal_route, thumbnail, icon, accent, featured, save_result, duration, players, how_to, philosophers, sort_order, visibility, class_ids) values ('comparative-advantage', '비교우위 무역 게임', '무엇을 만들고 무엇을 교환할까?', '통합사회 「시장과 경제」 단원과 연계해 국가 역할을 맡아 생산·교환하며 비교우위를 체험합니다.', '예정 콘텐츠', 'planned', null, null, null, '🚢', 'green', false, false, '15분', '모둠', array['국가와 자원을 배정받는다', '생산 품목을 정한다', '교환 후 총생산량을 비교한다']::text[], '{}', 7, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.games (id, title, tagline, description, type, status, external_url, internal_route, thumbnail, icon, accent, featured, save_result, duration, players, how_to, philosophers, sort_order, visibility, class_ids) values ('island-society', '무인도 사회계약', '규칙 없는 섬, 무엇부터 정할까?', '무인도에 표류한 학급이 함께 살아갈 규칙을 정하며 사회계약론과 정의의 원리를 탐구합니다.', '예정 콘텐츠', 'planned', null, null, null, '📜', 'gold', false, false, '20분', '학급', array['상황 카드를 확인한다', '규칙을 제안하고 투표한다', '규칙이 낳은 결과를 돌아본다']::text[], '{}', 8, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.daily_questions (id, question, hint, related, sort_order, visibility, class_ids) values ('q-happy-pig', '행복한 돼지와 불행한 소크라테스, 누가 더 행복할까?', '밀의 질적 공리주의와 벤담의 양적 공리주의를 떠올려 보세요.', array['mill', 'bentham']::text[], 0, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.daily_questions (id, question, hint, related, sort_order, visibility, class_ids) values ('q-lie', '거짓말이 누군가의 생명을 구한다면, 거짓말은 옳은 행동일까?', '칸트는 어떤 경우에도 거짓말을 해서는 안 된다고 보았습니다.', array['kant']::text[], 1, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.daily_questions (id, question, hint, related, sort_order, visibility, class_ids) values ('q-ai-responsibility', 'AI가 내린 결정으로 사고가 났다면, 책임은 누구에게 있을까?', '도덕적 행위자가 되려면 어떤 조건이 필요할까요?', array['kant', 'aristotle']::text[], 2, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.daily_questions (id, question, hint, related, sort_order, visibility, class_ids) values ('q-human-nature', '사람은 본래 선하게 태어날까, 악하게 태어날까?', '맹자와 순자의 대결!', array['mencius', 'xunzi']::text[], 3, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.daily_questions (id, question, hint, related, sort_order, visibility, class_ids) values ('q-gyges', '아무도 보지 않는다면, 나는 여전히 정직할까?', '플라톤 『국가』의 "기게스의 반지" 이야기를 찾아보세요.', array['plato']::text[], 4, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.daily_questions (id, question, hint, related, sort_order, visibility, class_ids) values ('q-career', '내 진로를 스스로 선택하지 않는다면, 그것은 누구의 삶일까?', '사르트르: 실존은 본질에 앞선다.', array['sartre']::text[], 5, 'public', '{}'::uuid[]) on conflict (id) do nothing;
insert into public.daily_questions (id, question, hint, related, sort_order, visibility, class_ids) values ('q-less-desire', '더 많이 가지는 것과 더 적게 원하는 것, 무엇이 행복에 가까울까?', '에피쿠로스와 노자는 비슷한 답을 했을지도 모릅니다.', array['epicurus', 'laozi']::text[], 6, 'public', '{}'::uuid[]) on conflict (id) do nothing;
